           ('pharmacology', 'biperiden_anticholinergic'),
           ('pharmacology', 'valbenazine_vmat2'),
           ('pharmacology', 'cholinesterase_donepezil'),
           ('pharmacology', 'pramipexole_gabapentin_rls'),
           ('pharmacology', 'ect_biological_acute'),
           ('pharmacology', 'vp_shunt_neurosurgery'),
           ('pharmacology', 'desmopressin_enuresis'),
           ('pharmacology', 'psychotherapy_first_no_drug')
         ) as src(kind, item_id)
          where src.kind = c.kind::text and src.item_id = c.item_id)
   and not exists (
         select 1 from public.cases_answer_key k
          where (c.kind::text = 'diagnosis'    and k.diagnosis_id    = c.item_id)
             or (c.kind::text = 'therapy'      and k.therapy_id      = c.item_id)
             or (c.kind::text = 'pharmacology' and k.pharmacology_id = c.item_id));

commit;
